date -u +%TZ; free -g | sed -n 2p
cat $R/sb_ph2fix/out/PH2FIX_REPORT.md; cat $R/sb_ph2fix/out/sb_ph2fix.tar.sha256; ls -la $R/sb_ph2fix/out/sb_ph2fix.tar
mkdir -p $R/sb_ph2rev/work; cp $R/sb_cursor_probe/AGENTS.md $R/sb_ph2rev/AGENTS.md
